const listTMUnits = `-- name: ListTMUnits :many
SELECT id, tenant_id, project_id, origin, translation_id, translation_revision, message_id, message_key, namespace, source_locale, target_locale, source_mf2, target_mf2, target_model, source_normalized, target_normalized, source_hash, signature, source_vars, hit_count, last_hit_at, created_by, created_at, updated_at, retired_at, retired_reason, retired_by FROM knowledge_tm_units
WHERE id > $1
  AND ($2::text IS NULL OR source_locale = $2)
  AND ($3::text IS NULL OR target_locale = $3)
  AND ($4::uuid IS NULL OR project_id = $4)
  AND ($5::uuid IS NULL OR translation_id = $5)
  -- projects limits project-owned rows to a project-scoped caller's
  -- projects (RFC 0006 §4.1); tenant-wide rows stay. Filtered here so a
  -- page's size says nothing about the others.
  AND ($6::uuid[] IS NULL OR project_id IS NULL OR project_id = ANY ($6::uuid[]))
  AND ($7::text = 'all'
       OR ($7::text = 'active' AND retired_at IS NULL)
       OR ($7::text = 'retired' AND retired_at IS NOT NULL))
ORDER BY id
LIMIT $8
`

type ListTMUnitsParams struct {
	After         uuid.UUID
	SourceLocale  pgtype.Text
	TargetLocale  pgtype.Text
	ProjectID     uuid.NullUUID
	TranslationID uuid.NullUUID
	Projects      []uuid.UUID
	State         string
	MaxRows       int32
}

// Units in id order after the cursor. state: active, retired or all.
func (q *Queries) ListTMUnits(ctx context.Context, arg ListTMUnitsParams) ([]KnowledgeTmUnit, error) {
	rows, err := q.db.Query(ctx, listTMUnits,
		arg.After,
		arg.SourceLocale,
		arg.TargetLocale,
		arg.ProjectID,
		arg.TranslationID,
		arg.Projects,
		arg.State,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []KnowledgeTmUnit
	for rows.Next() {
		var i KnowledgeTmUnit
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.ProjectID,
			&i.Origin,
			&i.TranslationID,
			&i.TranslationRevision,
			&i.MessageID,
			&i.MessageKey,
			&i.Namespace,
			&i.SourceLocale,
			&i.TargetLocale,
			&i.SourceMf2,
			&i.TargetMf2,
			&i.TargetModel,
			&i.SourceNormalized,
			&i.TargetNormalized,
			&i.SourceHash,
			&i.Signature,
			&i.SourceVars,
			&i.HitCount,
			&i.LastHitAt,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.RetiredAt,
			&i.RetiredReason,
			&i.RetiredBy,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

